command:
// Read the Sky — anyone can try (Stargazer guide §8.4).
//
// Ten minutes under an open sky and an Astronomy Lore or Occultism check against the region's Hard DC,
// 5 lower on an Exalted or Malefic day. The roll is secret; what it tells you is whispered to you.

const api = game.modules.get("isaacs-hb-pf2e")?.api;
const actor = canvas.tokens?.controlled?.[0]?.actor ?? game.user.character;
if (!api?.stargazer) ui.notifications.error("Isaac's Homebrew (PF2e) is not active.");
else await api.stargazer.readTheSky(actor);
